package dashboard.enterprise.agent.connector.resolution;
import dashboard.enterprise.agent.connector.audit.ConnectorAuditStore; import dashboard.enterprise.agent.connector.model.*; import dashboard.enterprise.agent.connector.provider.EnterpriseConnectorProvider; import dashboard.enterprise.agent.model.AgentContext; import dashboard.enterprise.agent.tool.PermissionLevel; import java.time.Instant; import java.util.Map;
public final class ConnectorRuntime { private final ConnectorResolver resolver; private final ConnectorAuditStore audit; public ConnectorRuntime(ConnectorResolver resolver,ConnectorAuditStore audit){this.resolver=resolver;this.audit=audit;}
 public ConnectorResponse invoke(AgentContext context,ConnectorRequest request,String preferredConnectorId,PermissionLevel permission,boolean approved)throws Exception{if(permission==PermissionLevel.PROHIBITED)throw new SecurityException("Connector capability is prohibited: "+request.capabilityId());if(permission==PermissionLevel.WRITE_WITH_APPROVAL&&!approved)throw new SecurityException("Human approval required for connector capability: "+request.capabilityId());EnterpriseConnectorProvider p=resolver.resolve(request.capabilityId(),preferredConnectorId);ConnectorResponse response=p.invoke(context,request);audit.append(new ConnectorAuditEvent("mapaf.connector.audit/v1",Instant.now().toString(),context.correlationId(),p.definition().connectorId(),request.capabilityId(),p.definition().mode().name(),response.successful()?"SUCCESS":"FAILED",Map.of("actor",context.actor())));return response;}}
